import json


def task_func(data=None):
    if data is None:
        with open("inputs/commits.json", "r", encoding="utf-8") as handle:
            data = json.load(handle)

    seen = set()
    days = {}
    different_times = 0
    for commit in data["commits"]:
        sha = commit["sha"]
        if sha in seen:
            continue
        seen.add(sha)

        day = commit["committed_at"][:10]
        if day not in days:
            days[day] = {"day": day, "commits": 0, "merges": 0}
        days[day]["commits"] += 1
        if len(commit["parent_shas"]) > 1:
            days[day]["merges"] += 1
        if commit["authored_at"] != commit["committed_at"]:
            different_times += 1

    report = {
        "head": data["head"],
        "unique_commits": len(seen),
        "committer_days": [days[day] for day in sorted(days)],
        "different_author_and_committer_times": different_times,
        "evidence": "captured_git_commit_metadata",
    }
    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle)
    return report

import json
from collections import deque


def task_func(data=None):
    if data is None:
        with open("inputs/ancestry.json", "r", encoding="utf-8") as handle:
            data = json.load(handle)

    graph = {commit["sha"]: commit["parent_shas"] for commit in data["commits"]}
    head = data["head"]
    distances = {head: 0}
    queue = deque([head])
    unobserved = set()

    while queue:
        sha = queue.popleft()
        if sha not in graph:
            unobserved.add(sha)
            continue
        for parent in graph[sha]:
            if parent not in distances:
                distances[parent] = distances[sha] + 1
                queue.append(parent)

    components = []
    for component, commit in sorted(data["reported_components"].items()):
        if commit is None:
            reachable = None
            hops = None
        elif commit in distances:
            reachable = True
            hops = distances[commit]
        else:
            reachable = None if unobserved else False
            hops = None
        components.append({
            "component": component,
            "reported_commit": commit,
            "reachable": reachable,
            "minimum_parent_hops": hops,
        })

    report = {
        "head": head,
        "graph_nodes": len(graph),
        "unobserved_parent_ids": sorted(unobserved),
        "components": components,
        "direct_service_health": "unknown",
        "evidence": "observed_git_ancestry_only",
    }
    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle)
    return report

import json


def task_func(data=None):
    if data is None:
        with open("inputs/pulls.json", "r", encoding="utf-8") as handle:
            data = json.load(handle)

    requests = data["pull_requests"]
    report = {
        "total": len(requests),
        "merged": [],
        "open": [],
        "closed_unmerged": [],
        "open_drafts": [],
        "evidence": "captured_public_pull_requests",
    }

    for request in requests:
        number = request["number"]
        if request["merged_at"] is not None:
            report["merged"].append(number)
        elif request["state"] == "open":
            report["open"].append(number)
        elif request["state"] == "closed":
            report["closed_unmerged"].append(number)

        if request["state"] == "open" and request["draft"] is True:
            report["open_drafts"].append(number)

    for key in ("merged", "open", "closed_unmerged", "open_drafts"):
        report[key].sort()

    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle)

    return report

import json
from datetime import datetime


def task_func(data=None):
    if data is None:
        with open("inputs/checks.json", "r", encoding="utf-8") as handle:
            data = json.load(handle)

    runs = data["workflow_runs"]
    latest = {}
    latest_keys = {}
    for run in runs:
        sha = run["head_sha"]
        key = (datetime.fromisoformat(run["updated_at"]), int(run["id"]))
        if sha not in latest_keys or key > latest_keys[sha]:
            latest[sha] = run
            latest_keys[sha] = key

    heads = {}
    for label, sha in data["heads"].items():
        run = latest.get(sha)
        reported_ci = "unknown"
        if run is not None and run["status"] == "completed":
            conclusion = run.get("conclusion")
            if conclusion == "success":
                reported_ci = "passed"
            elif conclusion in ("failure", "timed_out", "action_required"):
                reported_ci = "failed"
        heads[label] = {
            "head": sha,
            "latest_observed_run_id": run["id"] if run is not None else None,
            "reported_ci": reported_ci,
        }

    report = {
        "heads": heads,
        "observed_runs": len(runs),
        "total_reported_runs": data["total_reported_runs"],
        "coverage": "observed_runs_only",
        "direct_service_health": "unknown",
    }
    with open("report.json", "w", encoding="utf-8") as handle:
        json.dump(report, handle)
    return report
